import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Node.previousSibling()
 */
public class Node_previousSibling_TriageGen0Test {

    private Document doc;

    @Before
    public void setUp() {
        doc = Document.createShell("");
    }

    /**
     * Tests that previousSibling returns null when the node is the first child (index 0).
     * Covers the 'else' branch: if (index > 0) ... else return null;
     */
    @Test
    public void testPreviousSibling_FirstChildReturnsNull() {
        Element parent = doc.body();
        Element firstChild = parent.appendElement("div");
        Element secondChild = parent.appendElement("span");

        Assert.assertNull("The first child should have no previous sibling", firstChild.previousSibling());
    }

    /**
     * Tests that previousSibling returns the correct preceding node when index > 0.
     * Covers the 'if' branch: if (index > 0) return siblings.get(index-1);
     */
    @Test
    public void testPreviousSibling_MiddleChildReturnsPrevious() {
        Element parent = doc.body();
        Element first = parent.appendElement("div");
        Element second = parent.appendElement("span");
        Element third = parent.appendElement("p");

        Assert.assertEquals("The previous sibling of the second child should be the first child", 
                first, second.previousSibling());
        Assert.assertEquals("The previous sibling of the third child should be the second child", 
                second, third.previousSibling());
    }

    /**
     * Tests that previousSibling returns the correct node when it is the last child.
     */
    @Test
    public void testPreviousSibling_LastChildReturnsPrevious() {
        Element parent = doc.body();
        Element first = parent.appendElement("div");
        Element second = parent.appendElement("span");

        Assert.assertEquals(first, second.previousSibling());
    }

    /**
     * Tests the behavior when the parent has no children (should not be reachable via a valid node, 
     * but we test the logic via a detached node if possible, though siblingIndex depends on parent).
     * Since siblingIndex() relies on parentNode.childNodes, we ensure we test the logic path.
     */
    @Test
    public void testPreviousSibling_WithTextNodes() {
        Element parent = doc.body();
        parent.append("Text 1"); // TextNode
        Element div = parent.appendElement("div");
        parent.append("Text 2"); // TextNode

        // The sibling index of 'div' should be 1 (index 0 is TextNode)
        Assert.assertEquals("Previous sibling of div should be the TextNode", 
                parent.childNode(0), div.previousSibling());
    }
}
